import{_ as i,C as r,o as h,c as b,j as e,a as c,E as t,ak as a}from"./chunks/framework.DxrHb2fb.js";const v=JSON.parse('{"title":"Checkbox 复选框","description":"","frontmatter":{},"headers":[],"relativePath":"components/checkbox.md","filePath":"components/checkbox.md","lastUpdated":1789994612000}'),n={name:"components/checkbox.md"},s={id:"checkbox-复选框",tabindex:"-1"};function x(k,d,u,p,g,f){const l=r("Badge"),o=r("XhDemo");return h(),b("div",null,[e("h1",s,[d[0]||(d[0]=c("Checkbox 复选框 ",-1)),t(l,{type:"info",text:"alpha"}),d[1]||(d[1]=c()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#checkbox-复选框","aria-label":'Permalink to "Checkbox 复选框 <Badge type="info" text="alpha" />"'},"​",-1))]),d[3]||(d[3]=a('<p>用于选择一个或多个独立选项。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/checkbox" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/checkbox.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/checkbox" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/checkbox" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/checkbox.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>标记一个独立选项</p>',4)),t(o,{src:"checkbox/01-basic"}),d[4]||(d[4]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;checkbox&quot;</code>：<strong><code>root</code></strong> · <code>indicator</code> · <code>hidden-input</code> · <code>label</code> · <code>text</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="不确定状态" tabindex="-1">不确定状态 <a class="header-anchor" href="#不确定状态" aria-label="Permalink to &quot;不确定状态&quot;">​</a></h3><p>表示部分选中</p>',6)),t(o,{src:"checkbox/02-indeterminate"}),d[5]||(d[5]=e("h3",{id:"颜色",tabindex:"-1"},[c("颜色 "),e("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),d[6]||(d[6]=e("p",null,"tone 决定勾中后方框使用哪族颜色，因此这里都设为勾中",-1)),t(o,{src:"checkbox/03-tone"}),d[7]||(d[7]=e("h3",{id:"尺寸",tabindex:"-1"},[c("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[8]||(d[8]=e("p",null,"适配不同的界面密度",-1)),t(o,{src:"checkbox/04-size"}),d[9]||(d[9]=e("h3",{id:"禁用与只读",tabindex:"-1"},[c("禁用与只读 "),e("a",{class:"header-anchor",href:"#禁用与只读","aria-label":'Permalink to "禁用与只读"'},"​")],-1)),d[10]||(d[10]=e("p",null,"区分不可用与不可修改状态",-1)),t(o,{src:"checkbox/05-event"}),d[11]||(d[11]=e("h3",{id:"校验状态",tabindex:"-1"},[c("校验状态 "),e("a",{class:"header-anchor",href:"#校验状态","aria-label":'Permalink to "校验状态"'},"​")],-1)),d[12]||(d[12]=e("p",null,"标记必须处理的选项",-1)),t(o,{src:"checkbox/06-value-mapping"}),d[13]||(d[13]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>表单中的同意、订阅或启用选项。</li><li>需要表达部分选中的汇总状态。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>立即生效的设置使用<a href="./switch">开关</a>。</li><li>互斥选择使用<a href="./radio-group">单选组</a>。</li><li>管理一组值时使用<a href="./checkbox-group">复选框组</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持选中、未选中与 <code>indeterminate</code> 状态。</li><li>方框是字段家族的控制盒：canvas 底、描边与无影，勾中后以语气色填充，按下缩放并换底。</li><li><code>readOnly</code> 仍可聚焦并参与提交，<code>disabled</code> 不参与提交。</li><li>标签、三档尺寸、校验状态和自定义指示器均使用同一状态动画。</li><li><code>name</code> 与 <code>value</code> 通过隐藏字段参与原生表单。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>将文字直接放入默认插槽，整行即可点击。</li><li>成组选择使用<a href="./checkbox-group">复选框组</a>。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>始终提供可见标签或 <code>aria-label</code>。</li><li>半选只用于表示下级选项的汇总状态。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>不要用复选框表达互斥选项。</li><li>不要将半选状态作为第三个业务值。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-checkbox&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCheckbox</code></td></tr><tr><td>组合式函数</td><td><code>useCheckbox</code></td></tr><tr><td>状态机</td><td><code>checkboxMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/checkbox.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>checked</code></td><td><code>CheckboxCheckedState</code></td><td></td><td></td></tr><tr><td><code>defaultChecked</code></td><td><code>CheckboxCheckedState</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：不可勾选，但仍可聚焦、仍参与提交，对比度不降低。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改变呈现，不阻止交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起使用，只发无障碍属性，不自行拦截提交。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；提供后 hidden-input 才带 name 并参与提交。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>提交的值，默认 &#39;on&#39;，与原生复选框一致。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定选中态使用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定方框边长与勾选符号的字号档位。</td></tr><tr><td><code>onCheckedChange</code></td><td><code>(details: CheckboxCheckedChangeDetails) =&gt; void</code></td><td></td><td>checked 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>checked-change</code></td><td><code>CheckboxCheckedChangeDetails</code></td><td>checked 状态变化；detail 为 <code>{ checked: boolean }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCheckbox</code></td><td><code>default</code></td><td>—</td><td>方框旁的文字；未写时只有一个方框。</td></tr><tr><td><code>XhCheckbox</code></td><td><code>indicator</code></td><td>—</td><td>方框中的图形；未写时由皮肤绘制勾选标记。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>label</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>text</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>off</code> · <code>on</code> · <code>indeterminate</code></p><p><strong>事件</strong>：<code>TOGGLE</code> · <code>CHECK</code> · <code>UNCHECK</code> · <code>CONTROLLED.ON</code> · <code>CONTROLLED.OFF</code> · <code>CONTROLLED.INDETERMINATE</code> · <code>FORM.RESET</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>isCheckedControlled</code> · <code>defaultsToChecked</code> · <code>defaultsToIndeterminate</code> · <code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>checked</code></td><td><code>CheckboxCheckedState</code></td><td></td></tr><tr><td><code>setChecked</code></td><td><code>(next: boolean) =&gt; void</code></td><td>半选只能由 checked prop 给出，这里只接受全选 / 全不选。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单影子：勾选后才提交，半选按未勾选处理。提供 name 后才带 name。</td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;label&#39;]</code></td><td>包裹方框与文字的 &lt;label&gt;：点击文字即切换，方框的可及名来自文字。只在带文字时渲染。</td></tr><tr><td><code>getTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>方框旁的文字。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/checkbox/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in root, not disabled</td><td>切换 checked 状态</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>held in root, not disabled, not readOnly</td><td>按住期间投影 data-pressed，与指针 :active 同一副按压面；抬起或失焦撤下，按住途中转入禁用或只读也撤下。与勾选态互相独立</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-checked</code></td><td>&#39;mixed&#39; | &#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;checkbox&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/checkbox.css</code> 使用 <code>[data-scope=&quot;checkbox&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>root</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>root</code></td><td><code>data-xh-action-profile</code></td><td>&#39;icon&#39;</td></tr><tr><td><code>root</code></td><td><code>data-xh-action-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-xh-action-variant</code></td><td>&#39;outline&#39;</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>label</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>text</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>text</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-checkbox-bg</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code><br><code>readonly</code></td><td><code>--xh-bg-canvas</code></td><td>checkbox 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-bg-checked</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code><br><code>readonly</code><br><code>state=checked</code><br><code>state=indeterminate</code></td><td><code>--xh-_checkbox-accent</code></td><td>checkbox 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-bg-checked-pressed</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code><br><code>state=checked</code><br><code>state=indeterminate</code></td><td><code>--xh-_tone-active</code></td><td>checkbox 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-bg-disabled</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>disabled</code></td><td><code>--xh-bg-subtle</code></td><td>checkbox 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-bg-pressed</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-bg-subtle-hover</code></td><td>checkbox 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-border</code></td><td><code>label</code><br><code>root</code></td><td><code>border</code><br><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>contrast=more</code><br><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>not([data-readonly])</code><br><code>pressed</code><br><code>readonly</code><br><code>state=unchecked</code><br><code>where([data-contrast=&#39;more&#39;])</code></td><td><code>--xh-border-control</code><br><code>--xh-border-strong</code></td><td>checkbox 的 label、root 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-border-checked</code></td><td><code>label</code><br><code>root</code></td><td><code>border</code><br><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>not([data-readonly])</code><br><code>pressed</code><br><code>readonly</code><br><code>state=checked</code><br><code>state=indeterminate</code></td><td><code>--xh-_checkbox-accent</code></td><td>checkbox 的 label、root 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-border-disabled</code></td><td><code>root</code></td><td><code>border-color</code></td><td><code>disabled</code></td><td><code>--xh-border-default</code></td><td>checkbox 的 root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-border-hover</code></td><td><code>label</code><br><code>root</code></td><td><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>disabled</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>not([data-readonly])</code><br><code>pressed</code><br><code>readonly</code></td><td><code>--xh-border-control-hover</code></td><td>checkbox 的 label、root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-border-invalid</code></td><td><code>label</code><br><code>root</code></td><td><code>border</code><br><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>invalid</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>not([data-readonly])</code><br><code>pressed</code><br><code>readonly</code><br><code>state=checked</code><br><code>state=indeterminate</code></td><td><code>--xh-border-invalid</code></td><td>checkbox 的 label、root 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_checkbox-on-accent</code></td><td>checkbox 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-fg-disabled</code></td><td><code>indicator</code><br><code>root</code></td><td><code>background-color</code><br><code>color</code></td><td><code>disabled</code><br><code>state=indeterminate</code></td><td><code>--xh-fg-disabled</code></td><td>checkbox 的 indicator、root 部件 background-color、color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-fg-invalid</code></td><td><code>label</code><br><code>text</code></td><td><code>color</code></td><td><code>invalid</code></td><td><code>--xh-fg-danger</code></td><td>checkbox 的 label、text 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_checkbox-glyph</code></td><td>checkbox 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-indicator-fg</code></td><td><code>indicator</code></td><td><code>background-color</code></td><td><code>state=indeterminate</code></td><td><code>--xh-_checkbox-on-accent</code></td><td>checkbox 的 indicator 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>checkbox 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-label-fg-disabled</code></td><td><code>label</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>checkbox 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_checkbox-label-font-size</code></td><td>checkbox 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-label-gap</code></td><td><code>label</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_checkbox-label-gap</code></td><td>checkbox 的 label 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-label-leading</code></td><td><code>label</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-leading-normal</code></td><td>checkbox 的 label 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>checkbox 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-checkbox-shadow</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>none</code></td><td>checkbox 的 root 部件 box-shadow 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>opacity</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>hover: hover</code> · <code>pointer: coarse</code>：同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',58))])}const q=i(n,[["render",x]]);export{v as __pageData,q as default};
